import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"阿里故障复盘 Agent 系统","description":"生产级 Multi-Agent 复盘系统：Plan Agent + Task Expert + Report-Composer 协作、Memory 管理三步法、业务价值导向评测与提示词四轮演进。","frontmatter":{"title":"阿里故障复盘 Agent 系统","description":"生产级 Multi-Agent 复盘系统：Plan Agent + Task Expert + Report-Composer 协作、Memory 管理三步法、业务价值导向评测与提示词四轮演进。","domain":"tech","tags":["tech","case","agent","multi-agent","incident-review"],"navOrder":77,"topicId":"cases-alibaba-incident-review-agent","layer":"appendix","status":"case","nodeType":"evidence","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/cases/alibaba-incident-review-agent.md","filePath":"zh/tech/appendices/cases/alibaba-incident-review-agent.md","lastUpdated":1791166440000}'),o={name:"zh/tech/appendices/cases/alibaba-incident-review-agent.md"};function i(l,t,s,d,g,h){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="阿里故障复盘-agent-系统" tabindex="-1">阿里故障复盘 Agent 系统 <a class="header-anchor" href="#阿里故障复盘-agent-系统" aria-label="Permalink to &quot;阿里故障复盘 Agent 系统&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://new.qq.com/rain/a/20251009A01JF900" target="_blank" rel="noreferrer">别让故障复盘流于形式：用AI挖掘每一次&quot;跌倒&quot;的价值</a> ｜ 原始链接：<a href="https://www.bestblogs.dev/article/b68d8384" target="_blank" rel="noreferrer">https://www.bestblogs.dev/article/b68d8384</a> 文中效果数字（采纳率、耗时缩短）均归属该来源。</p></blockquote><h2 id="业务问题" tabindex="-1">业务问题 <a class="header-anchor" href="#业务问题" aria-label="Permalink to &quot;业务问题&quot;">​</a></h2><p>技术支持的目标是帮业务方做好稳定性，主张 <strong>blameless（无责）</strong> 复盘文化。复盘实操的难点：当事人不愿深写原因、长链路无人串联、恢复后报告从简、技术支持难以提出架构层关注点。</p><p>AI 赋能的核心能力：生成故障概述/时间线/影响面（连接监控与变更系统）、生成故障树分析 FTA、复盘数据结构化沉淀、风险识别与可视化、故障问答、深挖共性风险。</p><h2 id="multi-agent-架构" tabindex="-1">Multi-Agent 架构 <a class="header-anchor" href="#multi-agent-架构" aria-label="Permalink to &quot;Multi-Agent 架构&quot;">​</a></h2><p>以「故障复盘 Multi-Agent」为核心：</p><ul><li><strong>Plan Agent</strong>：解析用户意图，决策是 Ask 任务还是专业 Agent 任务</li><li><strong>Task Expert（任务专家 Agent）</strong>：被委派执行深度挖掘，自主多轮与底层服务交互</li><li><strong>Report-Composer</strong>：收集碎片化结论与证据，整合成有理有据的回答</li></ul><p>时序：用户 Web UI 提问 → Plan Agent 解析意图 → 子任务委派给 Task Expert → 专家调 API / 查 RAG 知识库 / 大模型推理 → Report-Composer 整合响应。</p><h2 id="memory-管理三步法" tabindex="-1">Memory 管理三步法 <a class="header-anchor" href="#memory-管理三步法" aria-label="Permalink to &quot;Memory 管理三步法&quot;">​</a></h2><p>长流程复盘任务中 Agent 上下文迅速膨胀（多轮对话 + 应急日志 + 会议记录，动辄数万 token，噪音极高）。原则：<strong>记得住关键，忘得掉干扰</strong>。</p><ol><li><strong>去噪</strong>：预处理剔除冗余与噪声</li><li><strong>Summary 提要</strong>：token 超阈值时用专门 LLM 把冗长历史提炼为结构化摘要，保留最近 N 条上下文与 System Prompt。采用 8 段式结构（模拟 SRE 复盘思维）：主要请求与意图 / 关键技术概念 / 文件与代码 / 错误与修复 / 问题解决过程 / 所有用户消息 / 待处理任务 / 当前工作状态</li><li><strong>保鲜</strong>：重要指令（System 消息、核心需求）重新注入记忆范围，防止遗忘</li></ol><h2 id="意图识别与交互" tabindex="-1">意图识别与交互 <a class="header-anchor" href="#意图识别与交互" aria-label="Permalink to &quot;意图识别与交互&quot;">​</a></h2><p><strong>入口分流</strong>：Chat 模式（沟通答疑，口语化提示词）vs Work 模式（专业化产出），少样本意图识别自动路由；同一领域工具聚合为独立「业务 Agent」，外层 <code>selectAgent</code> 统一包装——解决单 Agent 工具混杂、提示词膨胀、可维护性差的问题。</p><p><strong>三大交互能力</strong>：step 级流式执行与曝光控制（区分可透出/内部内容）；基于缓存的生产者/消费者会话管理（追加写入、按需读取）；前端组件封装为 Tool（识别「组件 JSON」后动态渲染卡片、图表、表单）。</p><h2 id="评测机制" tabindex="-1">评测机制 <a class="header-anchor" href="#评测机制" aria-label="Permalink to &quot;评测机制&quot;">​</a></h2><p>通用 Agent 评测（答案正确性）不适用——复盘的价值判断是「挖得深、提得准、改得动」。评测体系四阶段演进：</p><table tabindex="0"><thead><tr><th>阶段</th><th>方法</th><th>问题</th></tr></thead><tbody><tr><td>一</td><td>ROUGE/BLEU 词汇重合</td><td>堆砌常用词得高分，采纳率不高</td></tr><tr><td>二</td><td>BERTScore 语义相似</td><td>分数普遍偏高，区分不了表面相关</td></tr><tr><td>三</td><td>LLM-as-Judge</td><td>对「编造但听起来合理」的内容打分高</td></tr><tr><td>四</td><td><strong>业务价值导向打分</strong></td><td>结合标准答案关注点 + AI 生成关注点 + 复盘原文，从洞察深度、逻辑完整性、可执行性、证据支撑四维打分</td></tr></tbody></table><h2 id="提示词四轮演进" tabindex="-1">提示词四轮演进 <a class="header-anchor" href="#提示词四轮演进" aria-label="Permalink to &quot;提示词四轮演进&quot;">​</a></h2><ol><li><strong>V1 泛化生成</strong>：无约束靠常识输出 → 关注点太泛</li><li><strong>V2 风险标签</strong>：标签库框住 AI → 生搬硬套、吹毛求疵</li><li><strong>V3 标签拆分</strong>：5 个子集并行 → 标签无法穷举、维护成本高</li><li><strong>V4 回归问题本质</strong>：两阶段拆解（先提具体问题含服务名/接口/配置项实体，再严格基于文档分析）；摒弃标签库，分类后置；要求引用日志/配置/调用链证据；<strong>防幻觉——信息不足时宁可直接置空，宁可不说，不可乱说</strong></li></ol><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ol><li>Blameless 文化是前提，AI 放大工程师的智慧而非替代</li><li>Plan + Task Expert + Composer 的 Multi-Agent 分工支撑深度分析与结构化输出</li><li>Memory 三步法（去噪 → Summary → 保鲜）保证长流程不迷路、不遗忘、不超载</li><li>评测无银弹：相似性指标监控退化 + 业务价值导向打分衡量优化效果</li><li>提示词演进的本质：从「教 AI 该说什么」到「让 AI 真理解问题」</li></ol>',22)])])}const A=e(o,[["render",i]]);export{u as __pageData,A as default};
